    phrases: [
      { en: 'What does success look like for this feature in three months?', key: 'What does success look like', ko: '석 달 뒤 이 기능의 성공은 어떤 모습일까요?', when: '목표를 정할 때', when_en: 'When setting goals', meaning_en: 'How will we know this feature worked after three months?' },
      { en: "Let's frame this as a problem statement before we jump to solutions.", key: 'problem statement', ko: '해결책으로 넘어가기 전에 문제 정의부터 써 봐요.', when: '기획 초기에', when_en: 'Early in planning', meaning_en: 'Write down the problem clearly first.' },
      { en: 'Is this on the roadmap for this quarter or next?', key: 'on the roadmap', ko: '이건 이번 분기 로드맵에 있나요, 다음 분기인가요?', when: '일정을 확인할 때', when_en: 'When checking timing', meaning_en: 'When is this planned?' },
      { en: "We can't do everything, so what's the must-have for launch?", key: 'must-have', ko: '다 할 수는 없으니 출시에 꼭 필요한 건 뭔가요?', when: '범위를 좁힐 때', when_en: 'When narrowing scope', meaning_en: 'What is required for the first release?' },
      { en: 'This feels like a nice-to-have rather than a core need.', key: 'nice-to-have', ko: '이건 핵심 니즈라기보다 있으면 좋은 기능 같아요.', when: '우선순위를 논의할 때', when_en: 'When discussing priorities', meaning_en: 'It is useful, but not essential.' },
      { en: "What's the hypothesis we're testing with this experiment?", key: 'hypothesis', ko: '이 실험으로 검증하려는 가설이 뭔가요?', when: '실험을 설계할 때', when_en: 'When designing an experiment', meaning_en: 'What do we believe will happen, and why?' },
      { en: "Let's define the primary metric and a couple of guardrail metrics.", key: 'guardrail metrics', ko: '주요 지표 하나와 가드레일 지표 몇 개를 정해요.', when: '지표를 정할 때', when_en: 'When choosing metrics', meaning_en: 'Pick one main number to improve and some that must not get worse.' },
      { en: 'The variant improved sign-ups, but retention dropped slightly.', key: 'retention dropped', ko: '실험안이 가입은 늘렸지만 리텐션은 약간 떨어졌어요.', when: 'A/B 테스트 결과를 공유할 때', when_en: 'When sharing A/B test results', meaning_en: 'More people joined, but fewer stayed.' },
      { en: 'Is the result statistically significant, or do we need more traffic?', key: 'statistically significant', ko: '결과가 통계적으로 유의미한가요, 아니면 트래픽이 더 필요한가요?', when: '실험 결과를 해석할 때', when_en: 'When interpreting results', meaning_en: 'Is the result reliable, or do we need more users?' },
      { en: "Let's start with a small rollout to ten percent of users.", key: 'small rollout', ko: '전체 사용자 중 10%에게 먼저 소규모로 배포해요.', when: '출시 전략을 정할 때', when_en: 'When planning a launch', meaning_en: 'Release it to a small group first.' },
      { en: 'What user problem does this feature request actually solve?', key: 'feature request', ko: '이 기능 요청이 실제로 어떤 사용자 문제를 해결하나요?', when: '요청을 검토할 때', when_en: 'When reviewing a request', meaning_en: 'Which real user issue does this fix?' },
      { en: 'Could you share the business goals behind this request?', key: 'business goals', ko: '이 요청 뒤에 있는 비즈니스 목표를 공유해 주실 수 있을까요?', when: '요구사항의 배경을 물을 때', when_en: 'When asking for context', meaning_en: 'What is the company trying to achieve with this?' },
      { en: 'If we add this, what are we willing to drop?', key: 'willing to drop', ko: '이걸 추가하면 무엇을 빼야 할까요?', when: '범위를 조정할 때', when_en: 'When managing trade-offs', meaning_en: 'Adding work means removing something else.' },
      { en: "Let's use the RICE framework to rank these ideas.", key: 'RICE framework', ko: 'RICE 프레임워크로 아이디어 우선순위를 매겨요.', when: '우선순위를 정할 때', when_en: 'When prioritizing', meaning_en: 'Score ideas by reach, impact, confidence, and effort.' },
      { en: 'The funnel shows most users drop off at the second step.', key: 'drop off', ko: '퍼널을 보면 대부분 두 번째 단계에서 이탈해요.', when: '퍼널 데이터를 해석할 때', when_en: 'When reading funnel data', meaning_en: 'Many users quit on step two.' },
      { en: "What's the smallest thing we can ship to learn something?", key: 'smallest thing we can ship', ko: '뭔가 배울 수 있는 가장 작은 단위는 무엇일까요?', when: 'MVP를 정할 때', when_en: 'When defining an MVP', meaning_en: 'What is the simplest release that teaches us something?' },
      { en: "I'm worried this adds complexity without clear user value.", key: 'clear user value', ko: '이게 명확한 사용자 가치 없이 복잡도만 늘릴까 걱정돼요.', when: '기능 추가에 우려를 표할 때', when_en: 'When raising concerns about a feature', meaning_en: 'It makes things harder without helping users.' },
      { en: 'Can we look at the conversion rate by device type?', key: 'conversion rate', ko: '기기 유형별로 전환율을 볼 수 있을까요?', when: '데이터를 분석할 때', when_en: 'When analyzing data', meaning_en: 'Compare how many people complete the goal on each device.' },
      { en: 'Our north star metric is the number of monthly active users.', key: 'north star metric', ko: '우리의 핵심 지표는 월간 활성 사용자 수예요.', when: '팀 목표를 공유할 때', when_en: 'When sharing team goals', meaning_en: 'Our main measure of success is monthly users.' },
      { en: "Let's tie the design work back to this quarter's OKRs.", key: 'tie the design work back to', ko: '디자인 작업을 이번 분기 OKR과 연결해요.', when: '목표를 정렬할 때', when_en: 'When aligning with goals', meaning_en: 'Show how design supports the team goals.' },
      { en: "Let's write user stories so engineering knows the expected behavior.", key: 'user stories', ko: '개발팀이 기대 동작을 알 수 있게 사용자 스토리를 써요.', when: '요구사항을 정리할 때', when_en: 'When writing requirements', meaning_en: 'Describe needs from the user point of view.' },
      { en: 'What are the acceptance criteria for this ticket?', key: 'acceptance criteria', ko: '이 티켓의 인수 조건은 뭔가요?', when: '완료 기준을 확인할 때', when_en: 'When checking completion criteria', meaning_en: 'What must be true for this to be done?' },
      { en: 'The numbers look good, but the user comments tell a different story.', key: 'tell a different story', ko: '수치는 좋아 보이지만 사용자 의견은 다른 이야기를 해요.', when: '데이터를 해석할 때', when_en: 'When interpreting data', meaning_en: 'User comments do not match the positive numbers.' },
      { en: 'Can we sunset this feature, since almost nobody uses it?', key: 'sunset this feature', ko: '거의 아무도 안 쓰니 이 기능을 종료할 수 있을까요?', when: '기능 정리를 제안할 때', when_en: 'When proposing to remove a feature', meaning_en: 'Can we retire this unused feature?' },
      { en: 'This is a quick win that could ship in a single sprint.', key: 'quick win', ko: '이건 한 스프린트 안에 낼 수 있는 빠른 성과예요.', when: '작은 개선을 제안할 때', when_en: 'When proposing a small improvement', meaning_en: 'It is an easy change with fast results.' },
      { en: "Let's measure the impact two weeks after launch and decide then.", key: 'measure the impact', ko: '출시 2주 후에 효과를 측정하고 그때 결정해요.', when: '후속 결정을 미룰 때', when_en: 'When deferring a decision', meaning_en: 'Check results after two weeks before deciding.' },
      { en: "I'd push for fixing onboarding before we add any new features.", key: 'push for', ko: '새 기능을 더하기 전에 온보딩부터 고치자고 강하게 제안하고 싶어요.', when: '우선순위를 주장할 때', when_en: 'When advocating a priority', meaning_en: 'I strongly suggest fixing onboarding first.' },
      { en: 'Could we run a fake door test to gauge interest first?', key: 'fake door test', ko: '먼저 관심도를 보려고 페이크 도어 테스트를 해 볼까요?', when: '수요를 검증할 때', when_en: 'When validating demand', meaning_en: 'Show a button for a feature that does not exist yet to measure interest.' },
      { en: "Let's make sure design has a seat at the table during planning.", key: 'a seat at the table', ko: '기획 단계에서 디자인도 함께 참여할 수 있게 해요.', when: '디자인 참여를 요청할 때', when_en: 'When asking for design involvement', meaning_en: 'Include designers in planning discussions.' },
      { en: "The launch slipped by a week, so let's update the stakeholders.", key: 'slipped by a week', ko: '출시가 일주일 밀렸으니 이해관계자들에게 알려요.', when: '일정 변경을 알릴 때', when_en: 'When the schedule changes', meaning_en: 'The release is a week late, so tell everyone involved.' }
    ]
