  {
    id: 'collab',
    name: '협업·커뮤니케이션', name_en: 'Collaboration',
    tags: ['협업', '커뮤니케이션', '소통', '이해관계자', '얼라인', '반대 의견', '도움 요청', '슬랙', '동료', '팀워크', 'collaboration', 'collab', 'communication', 'stakeholder', 'stakeholders', 'alignment', 'disagree', 'help', 'slack', 'teamwork'],
    phrases: [
      { en: "I see where you're coming from, but I have a different take.", key: "where you're coming from", ko: '왜 그렇게 생각하시는지 알겠어요. 다만 저는 좀 다르게 봐요.', when: '정중하게 반대할 때', when_en: 'When disagreeing politely', meaning_en: 'I understand your view, but I think differently.' },
      { en: 'Could I get a second pair of eyes on this flow?', key: 'second pair of eyes', ko: '이 흐름 한번 같이 봐 주실 수 있을까요?', when: '검토를 부탁할 때', when_en: 'When asking for a review', meaning_en: 'Can someone else check this too?' },
      { en: 'I might be missing something, but why do we need this step?', key: 'I might be missing something', ko: '제가 놓친 게 있을 수도 있는데, 이 단계가 왜 필요한가요?', when: '조심스럽게 질문할 때', when_en: 'When questioning carefully', meaning_en: 'Maybe I do not understand, but why is this step here?' },
      { en: "Let's get everyone aligned before we present to leadership.", key: 'get everyone aligned', ko: '경영진에게 발표하기 전에 모두 생각을 맞춰요.', when: '중요한 발표 전에', when_en: 'Before an important presentation', meaning_en: 'Make sure the team agrees first.' },
      { en: "Thanks for flagging this; I'll take a look this afternoon.", key: 'Thanks for flagging', ko: '알려주셔서 감사해요. 오늘 오후에 확인해 볼게요.', when: '이슈 제보에 답할 때', when_en: 'When responding to a reported issue', meaning_en: 'Thanks for telling me; I will check it today.' },
      { en: 'Do you have a few minutes to talk through this?', key: 'talk through', ko: '이거 잠깐 같이 얘기할 시간 있으세요?', when: '짧은 논의를 요청할 때', when_en: 'When asking for a quick discussion', meaning_en: 'Can we discuss this briefly?' },
      { en: "I'd love to hear the engineering perspective on this.", key: 'engineering perspective', ko: '이 부분에 대한 개발 관점의 의견을 듣고 싶어요.', when: '다른 직군의 의견을 구할 때', when_en: 'When asking another discipline for input', meaning_en: 'What do developers think about this?' },
      { en: 'Can we disagree and commit so we can keep moving?', key: 'disagree and commit', ko: '의견은 달라도 일단 결정에 따르고 진행할까요?', when: '논의가 길어질 때', when_en: 'When a debate drags on', meaning_en: 'Accept the decision even if you disagree, and move forward.' },
      { en: 'Sorry to bug you, but do you have an update on the copy?', key: 'Sorry to bug you', ko: '귀찮게 해서 죄송한데, 문구 관련 업데이트 있을까요?', when: '업데이트를 재촉할 때', when_en: 'When nudging for an update', meaning_en: 'Sorry to interrupt; is there news on the text?' },
      { en: "Let's move this to a thread so the channel stays readable.", key: 'move this to a thread', ko: '채널이 읽기 편하도록 이건 스레드로 옮겨요.', when: '슬랙 채널을 정리할 때', when_en: 'When keeping Slack tidy', meaning_en: 'Reply in a thread instead of the main channel.' },
      { en: "I'm not sure I follow; could you give me an example?", key: "I'm not sure I follow", ko: '잘 이해가 안 되는데, 예시를 들어 주실 수 있을까요?', when: '설명이 이해되지 않을 때', when_en: 'When you do not understand', meaning_en: 'I do not understand, so please show an example.' },
      { en: 'Great catch! I completely missed that one.', key: 'Great catch', ko: '잘 찾으셨어요! 저는 완전히 놓쳤네요.', when: '동료가 실수를 찾아줬을 때', when_en: 'When a colleague spots a mistake', meaning_en: 'Thank you for noticing that.' },
      { en: 'Can I get your input before I finalize this?', key: 'get your input', ko: '확정하기 전에 의견 좀 들을 수 있을까요?', when: '의견을 구할 때', when_en: 'When asking for input', meaning_en: 'Please share your thoughts before I finish.' },
      { en: "I want to make sure we're solving the same problem.", key: 'solving the same problem', ko: '우리가 같은 문제를 풀고 있는지 확인하고 싶어요.', when: '관점이 엇갈릴 때', when_en: 'When perspectives differ', meaning_en: 'Let us check that we agree on the problem.' },
      { en: 'Who needs to sign off on this before we move forward?', key: 'sign off on this', ko: '진행하기 전에 누구의 승인이 필요한가요?', when: '의사결정자를 확인할 때', when_en: 'When identifying decision makers', meaning_en: 'Whose approval do we need?' },
      { en: "I'll keep the stakeholders in the loop with a weekly update.", key: 'in the loop', ko: '주간 업데이트로 이해관계자들에게 계속 공유할게요.', when: '공유 방식을 정할 때', when_en: 'When setting up communication', meaning_en: 'I will update everyone involved every week.' },
      { en: "I hear you, and I think we both want what's best for users.", key: "what's best for users", ko: '무슨 말인지 알아요. 우리 둘 다 사용자에게 가장 좋은 걸 원하잖아요.', when: '갈등을 완화할 때', when_en: 'When easing tension', meaning_en: 'We share the same goal of helping users.' },
      { en: 'Would it help if I put together a quick mockup to clarify?', key: 'Would it help if', ko: '이해를 돕도록 간단히 목업을 만들어 드리면 도움이 될까요?', when: '도움을 제안할 때', when_en: 'When offering help', meaning_en: 'I can make a quick design to explain.' },
      { en: "Let me play devil's advocate for a second.", key: "play devil's advocate", ko: '잠깐 일부러 반대 입장에서 말해 볼게요.', when: '다른 관점을 제시할 때', when_en: 'When offering a counterpoint', meaning_en: 'I will argue the other side to test the idea.' },
      { en: "I'd rather raise this now than find out after launch.", key: "I'd rather raise this now", ko: '출시 후에 알게 되느니 지금 말씀드리는 게 낫겠어요.', when: '우려를 미리 제기할 때', when_en: 'When raising a concern early', meaning_en: 'It is better to discuss the risk now.' },
      { en: 'Could you help me prioritize? I have three urgent requests.', key: 'help me prioritize', ko: '우선순위 정하는 것 좀 도와주실래요? 급한 요청이 세 개 있어요.', when: '업무가 몰릴 때', when_en: 'When overloaded', meaning_en: 'Please tell me which task to do first.' },
      { en: 'Happy to help! Just send over the details.', key: 'Happy to help', ko: '기꺼이 도와드릴게요! 자세한 내용만 보내 주세요.', when: '부탁을 수락할 때', when_en: 'When accepting a request', meaning_en: 'I am glad to help; send me the information.' },
      { en: "I don't have the bandwidth this week, but Sora might.", key: 'bandwidth', ko: '이번 주는 여유가 없는데, 소라 님은 가능할 수도 있어요.', when: '요청을 거절할 때', when_en: 'When declining a request', meaning_en: 'I am too busy, but Sora may be free.' },
      { en: 'Can we hop on a quick huddle to unblock this?', key: 'huddle', ko: '이거 풀려면 잠깐 허들로 얘기할까요?', when: '슬랙에서 빠르게 해결할 때', when_en: 'When resolving something fast on Slack', meaning_en: 'Let us do a quick voice call to solve this.' },
      { en: 'Please tag me if you need a design review.', key: 'tag me', ko: '디자인 리뷰가 필요하면 저를 태그해 주세요.', when: '요청 방법을 안내할 때', when_en: 'When explaining how to reach you', meaning_en: 'Mention me when you need a review.' },
      { en: "To make sure I understood, you'd like the summary at the top?", key: 'To make sure I understood', ko: '제가 제대로 이해했는지 확인하려고요. 요약을 맨 위에 두길 원하시는 거죠?', when: '요청을 확인할 때', when_en: 'When confirming a request', meaning_en: 'Let me repeat it back to check.' },
      { en: 'Can we find a middle ground between the two proposals?', key: 'middle ground', ko: '두 제안 사이에서 절충안을 찾을 수 있을까요?', when: '타협점을 찾을 때', when_en: 'When seeking a compromise', meaning_en: 'Is there an option that combines both ideas?' },
      { en: "I'd like to share some feedback; is now a good time?", key: 'is now a good time', ko: '피드백을 좀 드리고 싶은데 지금 괜찮으세요?', when: '피드백을 꺼낼 때', when_en: 'When starting a feedback conversation', meaning_en: 'May I give you feedback right now?' },
      { en: "Let's assume good intent; they probably didn't have the full context.", key: 'assume good intent', ko: '좋은 의도였다고 생각해요. 아마 전체 맥락을 몰랐을 거예요.', when: '오해를 풀 때', when_en: 'When defusing a misunderstanding', meaning_en: 'They likely meant well but lacked information.' },
      { en: "Let's not ping people after hours unless it's urgent.", key: 'after hours', ko: '급한 일이 아니면 업무 시간 이후에는 연락하지 말아요.', when: '슬랙 에티켓을 정할 때', when_en: 'When setting Slack etiquette', meaning_en: 'Avoid messaging people outside work time.' },
      { en: 'I want to push back a little on the timeline.', key: 'push back a little', ko: '일정에 대해서는 조금 다른 의견을 드리고 싶어요.', when: '일정에 이의를 제기할 때', when_en: 'When challenging a timeline', meaning_en: 'I am a bit concerned about the schedule.' },
      { en: "Let's escalate this if we can't resolve it by Friday.", key: 'escalate', ko: '금요일까지 해결이 안 되면 윗선에 올려요.', when: '문제가 해결되지 않을 때', when_en: 'When an issue stays stuck', meaning_en: 'Ask a manager to decide if it is not solved by Friday.' }
    ]
  }
